SELECT 'gongkao', '并列关系', 'kp-xingce-language-cloze-function-word-parallel', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "虚词辨析：并列关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "前后分句地位平等，没有主次先后之分。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、核心词汇"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "既...又...、一边...一边...、不是...而是...、是...不是...。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "“不是...而是”与“不是...就是”：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "“不是 A 而是 B”是并列关系中的【对立并列】（肯定B，否定A）。“不是 A 就是 B”是选择关系（两者必居其一）！"}]}]}]}$$ AS jsonb), NULL, '并列关系的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "逻辑填空", "并列关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_cloze_function_word_parallel", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
